module harmonic_sum (\n    input [9:0] n,\n    output reg [63:0] result\n);\n\n    // Combinational logic for harmonic sum computation\n    // Using Q32.32 fixed-point format: value * 2^32\n    \n    // Internal wire for harmonic sum accumulator\n    reg [63:0] harmonic_sum;\n    reg [31:0] inv_i;\n    integer i;\n    \n    always @(*) begin\n        // Initialize accumulator to zero\n        harmonic_sum = 64'd0;\n        \n        // Compute sum_{i=1}^{n} 1/i using integer division\n        // For each i, compute (2^32) / i\n        for (i = 1; i <= 1000; i = i + 1) begin\n            // Only process if current i <= n\n            if (i <= n) begin\n                // Calculate 2^32 / i\n                // Use 64-bit intermediate to avoid overflow\n                inv_i = 32'd0;\n                if (i != 0) begin\n                    inv_i = (64'd4294967296) / i; // 2^32 / i\n                end\n                harmonic_sum = harmonic_sum + inv_i;\n            end\n        end\n        \n        // Multiply by n to get final result\n        // Result = harmonic_sum * n\n        // harmonic_sum is already in Q32.32 format\n        // Multiplication gives Q64.64, we need Q32.32\n        // So we take lower 64 bits (or shift right by 32 and take lower 64)\n        result = harmonic_sum * n;\n    end\n\nendmodule